const staticData = $getWorkflowStaticData('global');

if (staticData.blCounter === undefined) {
  staticData.blCounter = 0;
}

const items = $input.all();

function generateTimestamp() {
  const now = new Date();
  const yy = String(now.getFullYear()).slice(-2);
  const MM = String(now.getMonth() + 1).padStart(2, '0');
  const dd = String(now.getDate()).padStart(2, '0');
  const HH = String(now.getHours()).padStart(2, '0');
  const mm = String(now.getMinutes()).padStart(2, '0');
  return `${yy}${MM}${dd}${HH}${mm}`;
}

function formatDateBC(dateValue) {
  const d = new Date(dateValue);
  const yyyy = d.getFullYear();
  const MM = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  return `${yyyy}-${MM}-${dd}`;
}

const liste = items.map(item => {

  const blRef = `BL-${generateTimestamp()}`;

  return {
    CodeFrs: item.json.CodeFrs,
    BLFrs: blRef,
    DateBC: formatDateBC(item.json.DateBC),
    N_BC: item.json.N_BC,
    CodeArticle: item.json.CodeArticle,
    Quantite: item.json.Quantite,
    N_B_transport: blRef,
    Matricule: 'A',
    Poids: 0.01,
    Marque: item.json.Marque,
    observation: "",
    email_expediteur: "developpeur.ia@jbel-annour.ma"
  };
});

return [
  {
    json: {
      data: liste,
      PSHNUM_0:$input.first().json.PSHNUM_0
    }
  }
];

const items = $input.all();
const outputItems = [];

for (const item of items) {
  const dataArray = item.json.data;
  const numero_da = item.json.PSHNUM_0; // lu ici, pour cet item précis

  for (const row of dataArray) {
    outputItems.push({
      json: {
        ...row,
        PSHNUM_0: numero_da
      }
    });
  }
}

return outputItems;
